"Cuando eliminas tu cuenta, eliminamos o anonimizamos tu información personal en un plazo razonable, salvo que debamos conservarla por motivos legales o de seguridad. Parte de la información puede permanecer en copias de seguridad durante un tiempo limitado.":"Quando você exclui sua conta, excluímos ou anonimizamos suas informações pessoais em um prazo razoável, salvo quando precisamos conservá-las por motivos legais ou de segurança. Parte das informações pode permanecer em cópias de segurança por um tempo limitado.",
"Cuando mencionamos \"Drex\", \"nosotros\" o \"nuestro\" en esta política, nos referimos a la entidad que opera estos productos y que actúa como responsable del tratamiento de tus datos.":"Quando mencionamos \"Drex\", \"nós\" ou \"nosso\" nesta política, nos referimos à entidade que opera estes produtos e que atua como responsável pelo tratamento dos seus dados.",
"Cuando participas en fiestas de voz o videollamadas, procesamos los datos técnicos necesarios para establecer y mantener la conexión (como datos de señalización y calidad de red). No grabamos el audio de tus llamadas sin tu conocimiento. En los mensajes, tratamos el contenido necesario para entregarlos, mostrar vistas previas y aplicar nuestros sistemas de seguridad.":"Quando você participa de festas de voz ou videochamadas, processamos os dados técnicos necessários para estabelecer e manter a conexão (como dados de sinalização e qualidade de rede). Não gravamos o áudio das suas chamadas sem o seu conhecimento. Nas mensagens, tratamos o conteúdo necessário para entregá-las, mostrar prévias e aplicar nossos sistemas de segurança.",
"Cuando recibes un nuevo mensaje":"Quando você recebe uma nova mensagem",
"Cuando se procese tu solicitud, la siguiente información se eliminará permanentemente de nuestros servidores activos:":"Quando sua solicitação for processada, as seguintes informações serão excluídas permanentemente dos nossos servidores ativos:",
