"Drex Música es gratis gracias a los anuncios":"O Drex Música é grátis graças aos anúncios",
"Drex es una plataforma social que te permite crear un perfil, publicar contenido (textos, fotos, videos), interactuar con otras personas mediante comentarios, reacciones y mensajes, participar en comunidades, unirte a fiestas de voz y descubrir contenido de tu interés.":"A Drex é uma plataforma social que permite criar um perfil, publicar conteúdo (textos, fotos, vídeos), interagir com outras pessoas por meio de comentários, reações e mensagens, participar de comunidades, entrar em festas de voz e descobrir conteúdo do seu interesse.",
"Drex está teniendo problemas de conexión. Tus datos están a salvo.":"A Drex está com problemas de conexão. Seus dados estão a salvo.",
"Drex no está dirigido a menores de 13 años. No recopilamos intencionalmente información personal de menores de 13 años. Si tienes entre 13 y 17 años, debes contar con el consentimiento de tu padre, madre o tutor para usar nuestros Productos, según lo exija la ley de tu país.":"A Drex não é destinada a menores de 13 anos. Não coletamos intencionalmente informações pessoais de menores de 13 anos. Se você tem entre 13 e 17 anos, precisa do consentimento do seu pai, mãe ou responsável para usar nossos Produtos, conforme exigido pela lei do seu país.",
"Drex no parece una copia de otra red porque no lo es. Cada pantalla se diseñó desde cero para que se sienta propia, no prestada.":"A Drex não parece uma cópia de outra rede porque não é. Cada tela foi desenhada do zero para parecer própria, não emprestada.",
