"Nuestra responsabilidad total por cualquier reclamación relacionada con estos Términos o los Servicios no excederá la cantidad que hayas pagado por los Servicios en los doce (12) meses anteriores a la reclamación, o cien dólares estadounidenses (USD 100), lo que sea mayor.":"Nossa responsabilidade total por qualquer reclamação relacionada a estes Termos ou aos Serviços não excederá o valor que você pagou pelos Serviços nos doze (12) meses anteriores à reclamação, ou cem dólares americanos (USD 100), o que for maior.",
