"Podemos actualizar esta Política de Privacidad periódicamente. La versión actualizada se identificará mediante la fecha de \"Última actualización\" y entrará en vigor tan pronto como sea accesible. Si realizamos cambios sustanciales, te lo notificaremos de forma destacada en la aplicación o por correo electrónico. Te recomendamos revisar esta política con frecuencia para estar informado sobre cómo protegemos tu información.":"Podemos atualizar esta Política de Privacidade periodicamente. A versão atualizada será identificada pela data de \"Última atualização\" e entrará em vigor assim que estiver acessível. Se fizermos mudanças substanciais, vamos notificá-lo de forma destacada no aplicativo ou por e-mail. Recomendamos revisar esta política com frequência para se manter informado sobre como protegemos suas informações.",
"Podemos actualizar estos Términos periódicamente. Te avisaremos de los cambios sustanciales mediante un aviso en la aplicación o por correo electrónico antes de que entren en vigor. Si continúas usando los Servicios después de la entrada en vigor de los cambios, se entenderá que los aceptas.":"Podemos atualizar estes Termos periodicamente. Vamos avisá-lo sobre mudanças substanciais por meio de um aviso no aplicativo ou por e-mail antes de entrarem em vigor. Se você continuar usando os Serviços após a entrada em vigor das mudanças, entender-se-á que você as aceita.",
"Podemos cambiar los precios o las funciones de pago avisándote con antelación razonable.":"Podemos alterar os preços ou os recursos de pagamento avisando você com antecedência razoável.",
"Podemos retirar contenido, limitar la visibilidad de cuentas o suspender cuentas que violen estas normas, con o sin aviso previo según la gravedad.":"Podemos remover conteúdo, limitar a visibilidade de contas ou suspender contas que violem estas normas, com ou sem aviso prévio conforme a gravidade.",
