"Publicar contenido ilegal, difamatorio, obsceno, amenazante o que incite al odio o a la violencia.":"Publicar conteúdo ilegal, difamatório, obsceno, ameaçador ou que incite ao ódio ou à violência.",
"Publicar contenido sexual explícito o explotar sexualmente a menores (tolerancia cero; lo reportaremos a las autoridades).":"Publicar conteúdo sexual explícito ou explorar sexualmente menores (tolerância zero; vamos denunciar às autoridades).",
