"Puedes controlar las cookies desde la configuración de tu navegador o dispositivo. Ten en cuenta que desactivarlas puede afectar el funcionamiento de algunas funciones.":"Você pode controlar os cookies nas configurações do seu navegador ou dispositivo. Lembre-se de que desativá-los pode afetar o funcionamento de alguns recursos.",
"Puedes ejercer muchos de estos derechos directamente desde los ajustes de la aplicación (por ejemplo, descargar tus datos o eliminar tu cuenta). Para otras solicitudes, contáctanos en zam.contact@yahoo.com indicando tu nombre de usuario y el derecho que deseas ejercer.":"Você pode exercer muitos desses direitos diretamente nas configurações do aplicativo (por exemplo, baixar seus dados ou excluir sua conta). Para outras solicitações, entre em contato em zam.contact@yahoo.com informando seu nome de usuário e o direito que deseja exercer.",
"Puedes eliminar tu cuenta en cualquier momento desde los ajustes de la aplicación. Nosotros podemos suspender o terminar tu acceso a los Servicios si violas estos Términos, si lo exige la ley o si discontinuamos los Servicios.":"Você pode excluir sua conta a qualquer momento nas configurações do aplicativo. Podemos suspender ou encerrar seu acesso aos Serviços se você violar estes Termos, se a lei exigir ou se descontinuarmos os Serviços.",
