"Que los bienes digitales son, por lo general, no reembolsables, salvo lo exigido por la ley o lo indicado en la oferta.":"Que os bens digitais são, em geral, não reembolsáveis, salvo o exigido por lei ou o indicado na oferta.",
"Que los pagos se procesan a través de terceros (como las tiendas de aplicaciones o pasarelas de pago) sujetos a sus propios términos.":"Que os pagamentos são processados por terceiros (como as lojas de aplicativos ou gateways de pagamento), sujeitos aos próprios termos deles.",
"Que los precios se muestran antes de confirmar la compra e incluyen los impuestos aplicables cuando corresponde.":"Que os preços são exibidos antes de confirmar a compra e incluem os impostos aplicáveis quando cabível.",
