"Si bloqueas esta cuenta desde el comentario, dejarás de ver su contenido, sus publicaciones y todo lo relacionado con ella.":"Se você bloquear esta conta a partir do comentário, vai deixar de ver o conteúdo, as publicações e tudo relacionado a ela.",
"Si crees que algún contenido en Drex infringe tus derechos de autor, puedes enviarnos una notificación a zam.contact@yahoo.com con la información necesaria para identificar la obra y el material infractor. Actuaremos conforme a la ley aplicable.":"Se você acredita que algum conteúdo na Drex infringe seus direitos autorais, pode nos enviar uma notificação para zam.contact@yahoo.com com as informações necessárias para identificar a obra e o material infrator. Vamos agir conforme a lei aplicável.",
"Si crees que fue un error, puedes apelar la decisión y la revisaremos.":"Se você acha que foi um erro, pode recorrer da decisão e vamos analisá-la.",
"Si descubrimos que hemos recopilado información personal de un menor de 13 años sin el consentimiento parental verificable, tomaremos medidas para eliminar esa información lo antes posible. Si crees que un menor nos ha proporcionado información personal, contáctanos de inmediato.":"Se descobrirmos que coletamos informações pessoais de um menor de 13 anos sem consentimento parental verificável, vamos tomar medidas para excluir essas informações o quanto antes. Se você acredita que um menor nos forneceu informações pessoais, entre em contato conosco imediatamente.",
"Si el problema continúa,":"Se o problema continuar,",
"Si eliminas tu cuenta, no podrás volver atrás. Todo se eliminará de los servidores:":"Se você excluir sua conta, não poderá voltar atrás. Tudo será excluído dos servidores:",
"Si existe una obligación legal, contractual o similar de conservarla.":"Se existir uma obrigação legal, contratual ou similar de conservá-la.",
"Si necesitamos la información para prestarte un servicio que solicitaste.":"Se precisarmos das informações para prestar um serviço que você solicitou.",
"Si no reconoces este acceso, cambia tu contraseña cuanto antes.":"Se você não reconhece este acesso, troque sua senha o quanto antes.",
"Si olvidas un dispositivo, el próximo inicio de sesión desde ahí generará una alerta.":"Se você esquecer um dispositivo, o próximo login a partir dele vai gerar um alerta.",
"Si resides en una jurisdicción con autoridad de protección de datos, también tienes derecho a presentar una reclamación ante dicha autoridad.":"Se você reside em uma jurisdição com autoridade de proteção de dados, também tem direito de apresentar uma reclamação a essa autoridade.",
"Si sos el papá, la mamá o un adulto responsable, pedile a la persona menor de edad el código de 6 dígitos que le aparece en su propia sección de Control parental, e ingresalo acá para supervisar su cuenta.":"Se você é o pai, a mãe ou um adulto responsável, peça à pessoa menor de idade o código de 6 dígitos que aparece na própria seção de Controle parental dela e digite-o aqui para supervisionar a conta.",
"Si tienes preguntas o inquietudes sobre esta Política de Privacidad o nuestras prácticas de datos, contáctanos en:":"Se você tiver dúvidas ou preocupações sobre esta Política de Privacidade ou nossas práticas de dados, entre em contato em:",
