"procesamos pagos, medimos el rendimiento de la aplicación y realizamos análisis para entender cómo se usan nuestros Productos.":"processamos pagamentos, medimos o desempenho do aplicativo e realizamos análises para entender como nossos Produtos são usados.",
"publicaciones":"publicações",
"publicaciones, fotos, videos, comentarios, reacciones, mensajes y notas que crees o compartas.":"publicações, fotos, vídeos, comentários, reações, mensagens e notas que você cria ou compartilha.",
"puedes designar a otra persona para que ejerza tus derechos en tu nombre, siempre que nos proporcione prueba de su autorización.":"você pode designar outra pessoa para exercer seus direitos em seu nome, desde que ela nos forneça prova da autorização dela.",
"realizamos investigaciones para mejorar nuestros Productos y desarrollar nuevas funciones, siempre protegiendo tu privacidad mediante técnicas como la agregación y la seudonimización cuando es posible.":"realizamos pesquisas para melhorar nossos Produtos e desenvolver novos recursos, sempre protegendo sua privacidade por meio de técnicas como agregação e pseudonimização quando possível.",
"recibir tus datos en un formato estructurado y transferirlos a otro proveedor.":"receber seus dados em um formato estruturado e transferi-los para outro provedor.",
"revisa periódicamente tu actividad de inicio de sesión, cierra sesión en dispositivos compartidos, ten cuidado con los mensajes sospechosos que pidan tus datos (phishing) y mantén actualizada la aplicación para recibir los últimos parches de seguridad.":"revise periodicamente sua atividade de login, encerre a sessão em dispositivos compartilhados, tome cuidado com mensagens suspeitas que peçam seus dados (phishing) e mantenha o aplicativo atualizado para receber os últimos patches de segurança.",
