"si alguna disposición se declara inválida, las demás seguirán vigentes.":"se alguma disposição for declarada inválida, as demais continuarão em vigor.",
"si mostramos publicidad, usamos tu información para mostrarte anuncios relevantes según tus intereses, tu actividad y tu información demográfica. Puedes controlar tus preferencias publicitarias en los ajustes.":"se mostrarmos publicidade, usamos suas informações para mostrar anúncios relevantes conforme seus interesses, sua atividade e suas informações demográficas. Você pode controlar suas preferências de publicidade nas configurações.",
"si nos das permiso, recopilamos datos de GPS para funciones como etiquetar el lugar de una publicación o mostrarte contenido cercano.":"se você nos der permissão, coletamos dados de GPS para recursos como marcar o local de uma publicação ou mostrar conteúdo próximo.",
"si realizas compras dentro de la aplicación, recopilamos los datos necesarios para procesar la transacción a través de nuestros proveedores de pago.":"se você fizer compras dentro do aplicativo, coletamos os dados necessários para processar a transação por meio dos nossos provedores de pagamento.",
"si se produce un cambio de propiedad o control de nuestros Productos, tu información puede transferirse al nuevo propietario.":"se ocorrer uma mudança de propriedade ou controle dos nossos Produtos, suas informações podem ser transferidas para o novo proprietário.",
"si tu país cuenta con leyes de privacidad específicas, aplicaremos los derechos y protecciones que correspondan según dicha normativa.":"se o seu país tiver leis de privacidade específicas, vamos aplicar os direitos e proteções correspondentes conforme essa legislação.",
"siguiendo":"seguindo",
"solicitar que eliminemos tu información personal.":"solicitar que excluamos suas informações pessoais.",
"solicitar una copia de la información personal que tenemos sobre ti.":"solicitar uma cópia das informações pessoais que temos sobre você.",
"te enviamos notificaciones sobre tu cuenta, actualizaciones de seguridad, cambios en nuestras políticas y, con tu consentimiento, comunicaciones de marketing.":"enviamos notificações sobre sua conta, atualizações de segurança, mudanças em nossas políticas e, com seu consentimento, comunicações de marketing.",
"tienes derecho a saber qué información personal recopilamos, a eliminarla, a corregirla, a optar por no participar en la venta o el uso compartido de tu información personal y a no recibir trato discriminatorio. En los últimos 12 meses hemos recopilado las categorías descritas en la sección 3. No vendemos tu información personal a cambio de dinero.":"você tem direito de saber quais informações pessoais coletamos, excluí-las, corrigi-las, optar por não participar da venda ou do compartilhamento das suas informações pessoais e não receber tratamento discriminatório. Nos últimos 12 meses, coletamos as categorias descritas na seção 3. Não vendemos suas informações pessoais em troca de dinheiro.",
"tienes derechos de confirmación, acceso, corrección, anonimización, portabilidad y eliminación, entre otros, los cuales puedes ejercer contactándonos.":"você tem direitos de confirmação, acesso, correção, anonimização, portabilidade e exclusão, entre outros, os quais pode exercer entrando em contato conosco.",
"tienes los derechos descritos en la sección 9, incluyendo el derecho a presentar una reclamación ante tu autoridad de control local. Nuestro representante para asuntos de protección de datos puede ser contactado en zam.contact@yahoo.com.":"você tem os direitos descritos na seção 9, incluindo o direito de apresentar uma reclamação à sua autoridade de controle local. Nosso representante para assuntos de proteção de dados pode ser contatado em zam.contact@yahoo.com.",
"tú":"você",
"usamos tu información para ofrecerte nuestros servicios, personalizar el contenido que ves (como el feed, las sugerencias de personas y comunidades), y mejorar la calidad y seguridad de la aplicación.":"usamos suas informações para oferecer nossos serviços, personalizar o conteúdo que você vê (como o feed, as sugestões de pessoas e comunidades), e melhorar a qualidade e a segurança do aplicativo.",
"verificamos cuentas, detectamos y combatimos el spam, el acoso, el contenido dañino y las conductas que violan nuestras normas. Usamos sistemas automatizados y revisión humana para estos fines.":"verificamos contas, detectamos e combatemos o spam, o assédio, o conteúdo prejudicial e as condutas que violam nossas normas. Usamos sistemas automatizados e revisão humana para esses fins.",
"verificaremos tu identidad antes de responder, para proteger tu información. Responderemos en los plazos exigidos por la ley aplicable (generalmente dentro de un mes, prorrogable en casos complejos). Si no podemos atender tu solicitud, te explicaremos los motivos.":"vamos verificar sua identidade antes de responder, para proteger suas informações. Vamos responder nos prazos exigidos pela lei aplicável (geralmente dentro de um mês, prorrogável em casos complexos). Se não pudermos atender sua solicitação, vamos explicar os motivos.",
