"Recopilamos el contenido, las comunicaciones y demás información que proporcionas cuando usas nuestros Productos, por ejemplo, cuando te registras para obtener una cuenta, creas o compartes contenido, o envías mensajes o te comunicas con otras personas. Esto puede incluir información presente en el contenido que creas o sobre dicho contenido, como el lugar donde se tomó una foto o la fecha en que se creó un archivo. También incluye lo que ves a través de las funciones de cámara que ofrecemos, para que podamos hacer cosas como sugerirte filtros o darte consejos sobre los formatos de cámara que podrían interesarte.":"Coletamos o conteúdo, as comunicações e outras informações que você fornece quando usa nossos Produtos, por exemplo, quando se registra para obter uma conta, cria ou compartilha conteúdo, ou envia mensagens ou se comunica com outras pessoas. Isso pode incluir informações presentes no conteúdo que você cria ou sobre esse conteúdo, como o local onde uma foto foi tirada ou a data em que um arquivo foi criado. Também inclui o que você vê por meio dos recursos de câmera que oferecemos, para que possamos fazer coisas como sugerir filtros ou dar dicas sobre os formatos de câmera que podem interessar a você.",
"Tú conservas los derechos sobre el contenido que publicas en Drex (\"Tu Contenido\"). Sin embargo, al publicarlo nos otorgas una licencia mundial, no exclusiva, gratuita y transferible para alojar, almacenar, reproducir, distribuir, mostrar y crear obras derivadas de Tu Contenido con el fin de operar, promocionar y mejorar nuestros Servicios. Esta licencia termina cuando eliminas Tu Contenido, salvo en los casos descritos en nuestra Política de Privacidad (por ejemplo, copias de seguridad o contenido compartido por otros).":"Você mantém os direitos sobre o conteúdo que publica no Drex (\"Seu Conteúdo\"). No entanto, ao publicá-lo, você nos concede uma licença mundial, não exclusiva, gratuita e transferível para hospedar, armazenar, reproduzir, distribuir, exibir e criar obras derivadas do Seu Conteúdo com o fim de operar, promover e melhorar nossos Serviços. Esta licença termina quando você exclui Seu Conteúdo, salvo nos casos descritos em nossa Política de Privacidade (por exemplo, cópias de segurança ou conteúdo compartilhado por outros).",
