"Las encuestas de más de 1 día son de Drex Orbit: se ajustó a 1 día.":"Votações com mais de 1 dia são do Drex Orbit: ajustado para 1 dia.",
"Mira este post en Drex.":"Veja este post no Drex.",
"Tu cuenta se creó, pero la foto no se pudo subir. Puedes agregarla desde tu perfil.":"Sua conta foi criada, mas não foi possível enviar a foto. Você pode adicioná-la no seu perfil.",
"Código reenviado. Revisa tu correo.":"Código reenviado. Confira seu e-mail.",
"No se pudo reenviar el código. Revisa tu conexión e inténtalo de nuevo.":"Não foi possível reenviar o código. Verifique sua conexão e tente de novo.",
"No puedes agregar a este usuario a un grupo contigo.":"Você não pode adicionar este usuário a um grupo com você.",
"La contraseña debe tener al menos 8 caracteres.":"A senha deve ter pelo menos 8 caracteres.",
"La contraseña es demasiado débil. Usa al menos 8 caracteres.":"A senha é muito fraca. Use pelo menos 8 caracteres.",
"Los destellos desaparecen a las 5 horas. Toca el bot\\u00f3n de abajo para ser la primera persona en compartir uno.":"Os destellos desaparecem em 5 horas. Toque no botão abaixo para ser a primeira pessoa a compartilhar um.",
"No se pudo abrir el chat. Int\\u00e9ntalo de nuevo.":"Não foi possível abrir o chat. Tente de novo.",
"Volver\\u00e1s a ver sus destellos":"Você voltará a ver os destellos dele",
"Ya no ver\\u00e1s sus destellos":"Você não verá mais os destellos dele",
"Nuevo inicio de sesi\\u00f3n":"Novo início de sessão",
"\\u00bfCerrar esta sesi\\u00f3n de Drex?":"Fechar esta sessão do Drex?",
"No se pudo cerrar la sesi\\u00f3n. Int\\u00e9ntalo de nuevo.":"Não foi possível fechar a sessão. Tente de novo.",
"\\u00bfCerrar todas las dem\\u00e1s sesiones de Drex? Los otros dispositivos deber\\u00e1n iniciar sesi\\u00f3n de nuevo.":"Fechar todas as outras sessões do Drex? Os outros dispositivos precisarão entrar novamente.",
"Se cerraron las dem\\u00e1s sesiones.":"As outras sessões foram fechadas.",
"Esa página no existe en Drex.":"Essa página não existe no Drex.",
