"No puedo abrir el editor desde aquí. Abre «Mis borradores» en la app y toca el borrador.":"Não consigo abrir o editor daqui. Abre \"Meus rascunhos\" no app e toca o rascunho.",
"No se pudo abrir el borrador. Inténtalo de nuevo.":"Não foi possível abrir o rascunho. Tenta de novo.",
"No se pudo actualizar el grupo. Inténtalo de nuevo.":"Não foi possível atualizar o grupo. Tenta de novo.",
"No se pudo actualizar la lista. Inténtalo de nuevo.":"Não foi possível atualizar a lista. Tenta de novo.",
"No se pudo cambiar el nombre de usuario (puede estar en uso o dentro del periodo de 7 días).":"Não foi possível mudar o nome de usuário (pode estar em uso ou dentro do período de 7 dias).",
"No se pudo pedir la confirmación.":"Não foi possível pedir a confirmação.",
"No supe convertir eso en pasos. Dime qué botón toco o qué campo lleno.":"Não soube transformar isso em passos. Me diz qual botão eu toco ou qual campo eu preencho.",
