"No sé a qué post te refieres. Pásame el enlace o descríbelo.":"Não sei a qual post você se refere. Me passa o link ou descreve.",
"No sé en qué pantalla estás, pero pregúntame lo que sea.":"Não sei em qual tela você está, mas me pergunta qualquer coisa.",
"No tienes hilos guardados. Di «guarda este hilo» cuando quieras conservar una investigación.":"Você não tem tópicos salvos. Diz \"salva este tópico\" quando quiser guardar uma investigação.",
"No tienes rutinas guardadas. Dime por ejemplo: «crea mi rutina de mañana: revisa notificaciones, dime qué pasó hoy».":"Você não tem rotinas salvas. Me diz por exemplo: \"cria minha rotina de amanhã: revisa notificações, me diz o que rolou hoje\".",
"No tienes vigilantes activos. Dime por ejemplo: «avísame cuando tenga un seguidor nuevo».":"Você não tem vigilantes ativos. Me diz por exemplo: \"me avisa quando eu tiver um seguidor novo\".",
