"Nota: los vigilantes funcionan mientras Drex está abierto en este dispositivo.":"Nota: os vigilantes funcionam enquanto o Drex está aberto neste dispositivo.",
"O escríbela como quieras: «mañana a las 9», «el lunes», «en 3 horas».":"Ou escreve como quiser: \"amanhã às 9\", \"na segunda\", \"em 3 horas\".",
